mapper.update:
update memory_fragment
set timeline_root = #{timelineRoot},
    content_text = #{contentText},
    searchable = #{searchable},
    updated_at = now()
where tenant_id = #{tenantId}
  and app_id = #{appId}
  and user_id = #{userId}
  and id = #{id}
  and deleted = false

update memory_fragment
set deleted = true,
    searchable = false,
    updated_at = now()
where tenant_id = #{tenantId}
  and app_id = #{appId}
  and user_id = #{userId}
  and id = #{id}
  and deleted = false

update memory_fragment
set deleted = true,
    searchable = false,
    updated_at = now()
where tenant_id = #{tenantId}
  and app_id = #{appId}
  and user_id = #{userId}
  and deleted = false

mapper.select:
select count(1)
from memory_fragment
where tenant_id = #{tenantId}
  and app_id = #{appId}
  and user_id = #{userId}
  and deleted = false
  and searchable = true

select count(1)
from memory_fragment
where tenant_id = #{tenantId}
  and app_id = #{appId}
  and user_id = #{userId}
  and deleted = false

  and timeline_root = #{timelineRoot}

select id,
       tenant_id,
       app_id,
       user_id,
       timeline_root,
       content_text,
       searchable,
       deleted,
       created_at
from memory_fragment
where tenant_id = #{tenantId}
  and app_id = #{appId}
  and user_id = #{userId}
  and deleted = false

  and timeline_root = #{timelineRoot}

order by created_at desc, id desc
limit #{limit}
offset #{offset}
